          { cn: "等候末日身体得赎，复活改变有荣光，靠主大能力灭死亡，像主荣体进天堂。", py: "děng hòu mò rì shēn tǐ dé shú, fù huó gǎi biàn yǒu róng guāng, kào zhǔ dà néng lì miè sǐ wáng, xiàng zhǔ róng tǐ jìn tiān táng。" }
