          { cn: "最大盼望等主再来，迎接我们回天乡，基业存天上不朽坏，我必享受福无疆。", py: "zuì dà pàn wàng děng zhǔ zài lái, yíng jiē wǒ men huí tiān xiāng, jī yè cún tiān shàng bù xiǔ huài, wǒ bì xiǎng shòu fú wú jiāng。" }
