          { cn: "满心盼望见我恩主，擦去我眼泪汪汪，主的应许信实不变，我所愿望必得偿。", py: "mǎn xīn pàn wàng jiàn wǒ ēn zhǔ, cā qù wǒ yǎn lèi wāng wāng, zhǔ de yīng xǔ xìn shí bú biàn, wǒ suǒ yuàn wàng bì dé cháng。" }
