          { cn: "我所欠罪债，主已还清洁；罪孽虽显如硃红，主使变白如雪。", py: "wǒ suǒ qiàn zuì zhài, zhǔ yǐ huán qīng jié; zuì niè suī xiǎn rú zhū hóng, zhǔ shǐ biàn bái rú xuě。" }
