          { cn: "应许我有圣灵帮助，只要靠祂圣名。", py: "yīng xǔ wǒ yǒu shèng líng bāng zhù, zhǐ yào kào tā shèng míng。" },
          { cn: "只要靠祂圣名。", py: "zhǐ yào kào tā shèng míng。" }
