          { cn: "现在切莫再犹豫,现在切莫再推辞;", py: "xiàn zài qiè mò zài yóu yù, xiàn zài qiè mò zài tuī cí;" },
          { cn: "现在将心门打开,让主耶稣进入你心。", py: "xiàn zài jiāng xīn mén dǎ kāi, ràng zhǔ yē sū jìn rù nǐ xīn。" }
