          { cn: "天父抚养；生命胜于饮食，", py: "tiān fù fǔ yǎng; shēng mìng shèng yú yǐn shí," },
          { cn: "身体胜于衣裳。先求神国神义，父必赏赐。", py: "shēn tǐ shèng yú yī shang。 xiān qiú shén guó shén yì, fù bì shǎng cì。" }
