          { cn: "今日召你，今日召你；", py: "jīn rì zhào nǐ, jīn rì zhào nǐ;" },
          { cn: "耶稣今召你，他温柔声今日召你。", py: "yē sū jīn zhào nǐ, tā wēn róu shēng jīn rì zhào nǐ。" }
