          { cn: "全能救主，全能救主，做我盾牌保护我，", py: "quán néng jiù zhǔ, quán néng jiù zhǔ, zuò wǒ dùn pái bǎo hù wǒ," },
          { cn: "全能救主，全能救主，做我盾牌保护我。", py: "quán néng jiù zhǔ, quán néng jiù zhǔ, zuò wǒ dùn pái bǎo hù wǒ。" }
