          { cn: "感谢我主恩宠，竟然救了我。", py: "gǎn xiè wǒ zhǔ ēn chǒng, jìng rán jiù le wǒ。" },
          { cn: "耶稣，主耶稣！祢为我钉十字架；我得恩浩大。", py: "yē sū, zhǔ yē sū! nǐ wéi wǒ dìng shí zì jià; wǒ dé ēn hào dà。" }
