          { cn: "难偿深恩、永爱、大德；", py: "nán cháng shēn ēn, yǒng ài, dà dé;" },
          { cn: "主爱如此圣善、奇妙；", py: "zhǔ ài rú cǐ shèng shàn, qí miào;" },
          { cn: "当献身心，全力报答。", py: "dāng xiàn shēn xīn, quán lì bào dá。" }
