          { cn: "竭力追求圣洁，遇难百折不回，", py: "jié lì zhuī qiú shèng jié, yù nán bǎi shé bú huí," },
          { cn: "专靠圣灵引导。至终主必接我？", py: "zhuān kào shèng líng yǐn dǎo。zhì zhōng zhǔ bì jiē wǒ?" }
