          { cn: "真神恩典如水长流，我们享受无穷极；", py: "zhēn shén ēn diǎn rú shuǐ zhǎng liú, wǒ men xiǎng shòu wú qióng jí;" },
          { cn: "今将身心献为活祭，求主悦纳莫丢弃。", py: "jīn jiāng shēn xīn xiàn wéi huó jì, qiú zhǔ yuè nà mò diū qì。" }
