          { cn: "虽有狮吼、狼号，我不惧不逃；", py: "suī yǒu shī hǒu, láng háo, wǒ bú jù bú táo;" },
          { cn: "过那死阴幽谷，也安然一宿，", py: "guò nà sǐ yīn yōu gǔ, yě ān rán yī xiǔ," },
          { cn: "等到东方破晓，我必得永福。", py: "děng dào dōng fāng pò xiǎo, wǒ bì dé yǒng fú。" }
