          { cn: "欢喜唱诗赞美救主，哈利路亚，哈利路亚！", py: "huān xǐ chàng shī zàn měi jiù zhǔ, hā lì lù yà, hā lì lù yà!" },
          { cn: "靠主天天背负重担，在世路上直到天家。", py: "kào zhǔ tiān tiān bèi fù zhòng dān, zài shì lù shàng zhí dào tiān jiā。" }
