          { cn: "那时蒙主擦去眼泪，在祂足前感谢跪拜。", py: "nà shí méng zhǔ cā qù yǎn lèi, zài tā zú qián gǎn xiè guì bài。" },
          { cn: "我必在天亲见主面，永远歌唱救我恩典；", py: "wǒ bì zài tiān qīn jiàn zhǔ miàn, yǒng yuǎn gē chàng jiù wǒ ēn diǎn;" },
          { cn: "我必在天亲见主面，永远歌唱救我恩典。", py: "wǒ bì zài tiān qīn jiàn zhǔ miàn, yǒng yuǎn gē chàng jiù wǒ ēn diǎn。" }
