          { cn: "主恩却充足，赐与我常丰盈，", py: "zhǔ ēn què chōng zú, cì yǔ wǒ cháng fēng yíng," },
          { cn: "火焰万无害，主无非存慈心；", py: "huǒ yàn wàn wú hài, zhǔ wú fēi cún cí xīn;" },
          { cn: "欲除我渣滓，而熬炼成精金，", py: "yù chú wǒ zhā zǐ, ér áo liàn chéng jīng jīn," },
          { cn: "欲除我渣滓，而熬炼成精金。", py: "yù chú wǒ zhā zǐ, ér áo liàn chéng jīng jīn。" }
