          { cn: "谨遵主命，工作努力，为主收割趁时机；", py: "jǐn zūn zhǔ mìng, gōng zuò nǔ lì, wéi zhǔ shōu gē chèn shí jī;" },
          { cn: "伸出镰刀收回庄稼，纳入天仓主欢喜。", py: "shēn chū lián dāo shōu huí zhuāng jià, nà rù tiān cāng zhǔ huān xǐ。" }
