          { cn: "白超乎雪，皎白超乎雪；因主给我洗，使我白超乎雪！", py: "bái chāo hū xuě, jiǎo bái chāo hū xuě; yīn zhǔ gěi wǒ xǐ, shǐ wǒ bái chāo hū xuě!" }
