          { cn: "要将灵恩赐我，舍己做我赎价，", py: "yào jiāng líng ēn cì wǒ, shě jǐ zuò wǒ shú jià," },
          { cn: "为我之罪被打被骂，我用何法报答？", py: "wèi wǒ zhī zuì bèi dǎ bèi mà, wǒ yòng hé fǎ bào dá?" }
