          { cn: "离去光明宝座，受苦受害至极，", py: "lí qù guāng míng bǎo zuò, shòu kǔ shòu hài zhì jí," },
          { cn: "主既为我丢弃一切，为主我何舍弃？", py: "zhǔ jì wèi wǒ diū qì yī qiè, wèi zhǔ wǒ hé shě qì?" }
